/**
 * @return {Object}
 */
var createInfiniteObject = function() {
    return new Proxy({}, {
        get(target, prop) {
            return () => String(prop);
        }
    });
};

function createInfiniteObject(): Record<string, () => string> {
    return new Proxy({}, {
        get(target, prop: string) {
            return () => String(prop);
        }
    });
}
